const stopsData = MOCK.stops;

const shapesData = MOCK.shapes;

export async function initMap() {
    // Dynamically import the library only on the client side
    const {createMap, WeatherLayer} = await import("@milemaker/milemaker-js");

    const map = await createMap({
        container: "map",
        baseApiUrl: process.env.NEXT_PUBLIC_MILEMAKER_BASE_API_URL ?? "",
        accessToken: process.env.NEXT_PUBLIC_MILEMAKER_ACCESS_TOKEN ?? "",
    });
    console.log("map", map);
    map.controls.createBaseLayerControl();
    map.controls.createOverlayLayerControl();

    const routeColor = "purple";

    // Create controls
    map.controls.createZoomControl();
    map.controls.createCurrentPositionControl();

    // Create overlay control with weather alerts integration
    map.controls.createOverlayLayerControl({
        onShow: (layerName) => {
            // When alerts layer is shown, display alerts for current route
            if (layerName === "alerts" && route) {
                const coordinates = route.shape.getLonLatLikes();
                map.actions.weatherAlertsActions.show(coordinates, {strokeColor: routeColor});
            }
        },
        onHide: (layerName) => {
            // When alerts layer is hidden, hide the weather alerts
            if (layerName === "alerts") {
                map.actions.weatherAlertsActions.hide();
            }
        }
    });

    // @ts-ignore
    let route: any;

    async function addRoute() {
        if(route){
            return;
        }

        route = map.actions.createRoute({
            // @ts-ignore
            stops: stopsData.map(({coordinate}) => coordinate),
            shapes: shapesData
        }, {
            stopMarkersOptions: {
                color: routeColor
            },
            shapeOptions: { color: routeColor }
        });

        route.fitIntoBounds();

        // Show weather alerts if alerts layer is currently visible
        const isAlertsVisible = map.actions.weatherLayerActions.getIsVisible(WeatherLayer.ALERTS);
        if (isAlertsVisible) {
            const coordinates = route.shape.getLonLatLikes();
            await map.actions.weatherAlertsActions.show(coordinates, {strokeColor: routeColor});
        }
    }

    function removeRoute() {
        if (!route) {
            return;
        }

        // Hide weather alerts when removing route
        map.actions.weatherAlertsActions.hide();

        route.hide();
        route = undefined;
        map.actions.resetPan();
    }

    return { addRoute, removeRoute };
}